```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // RecordSeen marks every considered item id as seen in the
        // read-write 'seen' store, so a later run does not reconsider them.
        // Authority: aap:caps/state-rw@0.1.0 only.
        let mut recorded: u32 = 0;

        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        // ensures recorded >= 0 holds trivially: recorded is a u32.
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
